package net.officefloor.hq.app.access;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.DatedSettings;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** A sheet's roles and settings. The signed-in user's name comes in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class AccessController {

    public record RoleView(String user, String role) {

        static RoleView of(SheetRole r) {
            return new RoleView(r.getUserName(), r.getRole().key());
        }
    }

    /**
     * The sheet's settings as shown, each dated one the value in force on the sheet's today; a limit is a
     * figure with two decimals, null for none; so is the floor;
     * the terms are a number of days, and so are the terms of grades A, B and C, null for a grade without
     * its own (it uses the sheet's); the late percent is a figure with two decimals; the policy date and
     * the period numbering from are dates (yyyy-mm-dd), null when blank; the grace days are a number of days, null
     * when blank (off); the cap is a figure with two
     * decimals, null for none; so are the proof threshold and the note threshold. Each entry of the permission matrix (open, settle,
     * void, reassign, close, reopen) is the roles that may take the action as written, comma separated; null
     * when blank (the standing rule). The entry date is a date (yyyy-mm-dd), null when blank (off). The grace
     * days of grades A, B and C are a number of days, null for a grade with none; the proof thresholds of
     * grades A, B and C are figures with two decimals, null for a grade with none (it uses the sheet's).
     */
    public record SettingsView(String clerkLimit, String floor, String terms, String termsA, String termsB,
            String termsC, String latePct, String policyDate, String periodNumberingFrom, String graceDays,
            String cap, String proofThreshold, String noteThreshold, String permOpen, String permSettle, String permVoid, String permReassign,
            String permClose, String permReopen, String entryDate, String graceA, String graceB, String graceC,
            String proofThresholdA, String proofThresholdB, String proofThresholdC) {

        static SettingsView of(DatedSettings dated, LocalDate today, LocalDate policyDate, LocalDate periodNumberingFrom,
                Integer graceDays, LocalDate entryDate) {
            return new SettingsView(text(dated.clerkLimit(today)), dated.floor(today).toPlainString(),
                    Integer.toString(dated.terms(today)), text(dated.gradeTerms("A", today)),
                    text(dated.gradeTerms("B", today)), text(dated.gradeTerms("C", today)),
                    dated.latePct(today).toPlainString(),
                    policyDate == null ? null : policyDate.toString(),
                    periodNumberingFrom == null ? null : periodNumberingFrom.toString(), text(graceDays),
                    text(dated.cap(today)), text(dated.proofThreshold(today)), text(dated.noteThreshold(today)),
                    perm(dated, Permission.OPEN, today), perm(dated, Permission.SETTLE, today),
                    perm(dated, Permission.VOID, today), perm(dated, Permission.REASSIGN, today),
                    perm(dated, Permission.CLOSE, today), perm(dated, Permission.REOPEN, today),
                    entryDate == null ? null : entryDate.toString(), text(grace(dated, "A", today)),
                    text(grace(dated, "B", today)), text(grace(dated, "C", today)),
                    text(dated.gradeProofThreshold("A", today)), text(dated.gradeProofThreshold("B", today)),
                    text(dated.gradeProofThreshold("C", today)));
        }

        /** The grade's grace days in force on the date as written; null when it has none then. */
        private static String grace(DatedSettings dated, String grade, LocalDate today) {
            return dated.on(DatedSettings.gradeGraceKey(grade), today).orElse(null);
        }

        private static String perm(DatedSettings dated, Permission permission, LocalDate today) {
            return dated.on(permission.key(), today).orElse(null);
        }

        private static String text(Object value) {
            return value == null ? null : value instanceof BigDecimal d ? d.toPlainString() : value.toString();
        }
    }

    /** A delegation of the steward role: the user, the steward who delegated, and its dates (yyyy-mm-dd), inclusive. */
    public record DelegationView(long id, String user, String by, String from, String to) {

        static DelegationView of(Delegation d) {
            return new DelegationView(d.getId(), d.getUserName(), d.getDelegatedBy(), d.getFromDate().toString(),
                    d.getToDate().toString());
        }
    }

    public record AccessView(List<RoleView> roles, SettingsView settings, List<DelegationView> delegations) {
    }

    /** A user name and the dates (yyyy-mm-dd) the steward role is delegated to it for; a blank from-date is the sheet's today. */
    public record DelegateForm(@NotBlank @Size(max = 200) String user, @Pattern(regexp = DATE) String from,
            @NotBlank @Pattern(regexp = DATE) String to) {
    }

    /** A user name and a role: clerk, steward or viewer. */
    public record RoleForm(@NotBlank @Size(max = 200) String user, @NotNull @Pattern(regexp = "clerk|steward|viewer") String role) {
    }

    /**
     * The settings to save; one left out (null) is kept as it is. A clerk limit is 0.00 or more with up
     * to two decimals, blank meaning no limit; so is a floor, blank putting back 1.00. The terms are a
     * whole number of days, blank putting back 14; so are a grade's own terms, blank removing them (the
     * grade then uses the sheet's). The late percent is 0.00 or more with up to two
     * decimals, blank putting back 0.00. The policy date is a date (yyyy-mm-dd), blank meaning the
     * sheet's today. The period numbering from is a date (yyyy-mm-dd), blank meaning off. The grace days are a whole number of
     * days, blank meaning off; not dated. The cap is 0.00
     * or more with up to two decimals, blank meaning no cap; so are the proof threshold and the note threshold, blank meaning none. Each setting that carries a figure takes a
     * from-date (yyyy-mm-dd) its value is in force from, blank or left out meaning the sheet's today. Each
     * entry of the permission matrix is a comma separated list of roles (clerk, steward), blank putting back
     * the standing rule; it is not dated. The entry date is a date (yyyy-mm-dd), blank meaning off; not
     * dated. A grade's grace days are a whole number of days, blank meaning none; dated. A grade's proof
     * threshold is 0.00 or more with up to two decimals, blank meaning none (the sheet's); dated.
     */
    public record SettingsForm(@Pattern(regexp = "(\\d{1,12}(\\.\\d{1,2})?)?") String clerkLimit,
            @Pattern(regexp = "(\\d{1,12}(\\.\\d{1,2})?)?") String floor,
            @Pattern(regexp = "(\\d{1,5})?") String terms,
            @Pattern(regexp = "(\\d{1,5})?") String termsA,
            @Pattern(regexp = "(\\d{1,5})?") String termsB,
            @Pattern(regexp = "(\\d{1,5})?") String termsC,
            @Pattern(regexp = "(\\d{1,10}(\\.\\d{1,2})?)?") String latePct,
            @Pattern(regexp = "(\\d{4}-\\d{2}-\\d{2})?") String policyDate,
            @Pattern(regexp = "(\\d{4}-\\d{2}-\\d{2})?") String periodNumberingFrom,
            @Pattern(regexp = "(\\d{1,5})?") String graceDays,
            @Pattern(regexp = "(\\d{1,12}(\\.\\d{1,2})?)?") String cap,
            @Pattern(regexp = "(\\d{1,12}(\\.\\d{1,2})?)?") String proofThreshold,
            @Pattern(regexp = "(\\d{1,12}(\\.\\d{1,2})?)?") String noteThreshold,
            @Pattern(regexp = DATE) String clerkLimitFrom,
            @Pattern(regexp = DATE) String floorFrom,
            @Pattern(regexp = DATE) String termsFrom,
            @Pattern(regexp = DATE) String termsAFrom,
            @Pattern(regexp = DATE) String termsBFrom,
            @Pattern(regexp = DATE) String termsCFrom,
            @Pattern(regexp = DATE) String latePctFrom,
            @Pattern(regexp = DATE) String capFrom,
            @Pattern(regexp = DATE) String proofThresholdFrom,
            @Pattern(regexp = DATE) String noteThresholdFrom,
            @Pattern(regexp = Permission.ROLES) String permOpen,
            @Pattern(regexp = Permission.ROLES) String permSettle,
            @Pattern(regexp = Permission.ROLES) String permVoid,
            @Pattern(regexp = Permission.ROLES) String permReassign,
            @Pattern(regexp = Permission.ROLES) String permClose,
            @Pattern(regexp = Permission.ROLES) String permReopen,
            @Pattern(regexp = "(\\d{4}-\\d{2}-\\d{2})?") String entryDate,
            @Pattern(regexp = "(\\d{1,5})?") String graceA,
            @Pattern(regexp = "(\\d{1,5})?") String graceB,
            @Pattern(regexp = "(\\d{1,5})?") String graceC,
            @Pattern(regexp = DATE) String graceAFrom,
            @Pattern(regexp = DATE) String graceBFrom,
            @Pattern(regexp = DATE) String graceCFrom,
            @Pattern(regexp = "(\\d{1,12}(\\.\\d{1,2})?)?") String proofThresholdA,
            @Pattern(regexp = "(\\d{1,12}(\\.\\d{1,2})?)?") String proofThresholdB,
            @Pattern(regexp = "(\\d{1,12}(\\.\\d{1,2})?)?") String proofThresholdC,
            @Pattern(regexp = DATE) String proofThresholdAFrom,
            @Pattern(regexp = DATE) String proofThresholdBFrom,
            @Pattern(regexp = DATE) String proofThresholdCFrom) {
    }

    /** A from-date: a date (yyyy-mm-dd), or blank for the sheet's today. */
    private static final String DATE = "(\\d{4}-\\d{2}-\\d{2})?";

    private final AccessService service;

    public AccessController(AccessService service) {
        this.service = service;
    }

    @GetMapping("/access")
    public AccessView get(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        String sheet = sheetId.trim();
        return new AccessView(service.roles(sheet).stream().map(RoleView::of).toList(),
                settings(sheet), delegations(sheet));
    }

    @PostMapping("/delegations")
    public List<DelegationView> delegate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody DelegateForm form) {
        String sheet = sheetId.trim();
        LocalDate from = form.from() == null || form.from().isEmpty() ? service.today(sheet) : LocalDate.parse(form.from());
        service.delegate(sheet, user.trim(), form.user().trim(), from, LocalDate.parse(form.to()));
        return delegations(sheet);
    }

    private List<DelegationView> delegations(String sheet) {
        return service.delegations(sheet).stream().map(DelegationView::of).toList();
    }

    @PutMapping("/roles")
    public RoleView setRole(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody RoleForm form) {
        Role role = Role.of(form.role()).orElseThrow();
        return RoleView.of(service.setRole(sheetId.trim(), user.trim(), form.user().trim(), role));
    }

    @PutMapping("/settings")
    public SettingsView setSettings(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody SettingsForm form) {
        String sheet = sheetId.trim();
        Map<String, AccessService.Dated> gradeTerms = new LinkedHashMap<>();
        gradeTerms.put("A", dated(form.termsA(), form.termsAFrom()));
        gradeTerms.put("B", dated(form.termsB(), form.termsBFrom()));
        gradeTerms.put("C", dated(form.termsC(), form.termsCFrom()));
        Map<String, AccessService.Dated> gradeGrace = new LinkedHashMap<>();
        gradeGrace.put("A", dated(form.graceA(), form.graceAFrom()));
        gradeGrace.put("B", dated(form.graceB(), form.graceBFrom()));
        gradeGrace.put("C", dated(form.graceC(), form.graceCFrom()));
        Map<String, AccessService.Dated> gradeProofThreshold = new LinkedHashMap<>();
        gradeProofThreshold.put("A", dated(form.proofThresholdA(), form.proofThresholdAFrom()));
        gradeProofThreshold.put("B", dated(form.proofThresholdB(), form.proofThresholdBFrom()));
        gradeProofThreshold.put("C", dated(form.proofThresholdC(), form.proofThresholdCFrom()));
        AccessService.Dated clerkLimit = dated(form.clerkLimit(), form.clerkLimitFrom());
        AccessService.Dated floor = dated(form.floor(), form.floorFrom());
        AccessService.Dated terms = dated(form.terms(), form.termsFrom());
        AccessService.Dated latePct = dated(form.latePct(), form.latePctFrom());
        AccessService.Dated cap = dated(form.cap(), form.capFrom());
        Map<Permission, String> permissions = new EnumMap<>(Permission.class);
        permissions.put(Permission.OPEN, form.permOpen());
        permissions.put(Permission.SETTLE, form.permSettle());
        permissions.put(Permission.VOID, form.permVoid());
        permissions.put(Permission.REASSIGN, form.permReassign());
        permissions.put(Permission.CLOSE, form.permClose());
        permissions.put(Permission.REOPEN, form.permReopen());
        service.setSettings(sheet, user.trim(), clerkLimit, floor, terms, gradeTerms, latePct, form.policyDate(),
                form.periodNumberingFrom(), form.graceDays(), gradeGrace, cap, dated(form.proofThreshold(), form.proofThresholdFrom()),
                dated(form.noteThreshold(), form.noteThresholdFrom()), permissions, form.entryDate(), gradeProofThreshold);
        return settings(sheet);
    }

    private SettingsView settings(String sheet) {
        return SettingsView.of(service.settings(sheet), service.today(sheet), service.policyDate(sheet),
                service.periodNumberingFrom(sheet), service.graceDays(sheet), service.entryDate(sheet));
    }

    /** A dated setting's value with its from-date (blank or left out: the sheet's today); null when the value is left out. */
    private static AccessService.Dated dated(String value, String from) {
        return value == null ? null
                : new AccessService.Dated(value, from == null || from.isEmpty() ? null : LocalDate.parse(from));
    }

    /** A policy date, period numbering from or from-date that is no date on the calendar: the save is refused and changes nothing. */
    @ExceptionHandler(DateTimeParseException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void noSuchDate() {
    }

    /** A delegation by anyone but a steward, or with its to-date before its from-date: refused, changing nothing. */
    @ExceptionHandler(DelegationRefused.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void delegationRefused() {
    }

    /** Another user set a role for the same name at the same moment: this one is refused. */
    @ExceptionHandler(DataIntegrityViolationException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void roleTaken() {
    }
}
package net.officefloor.hq.app.access;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.DatedSettings;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetArchived;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.sheet.SheetSetting;
import net.officefloor.hq.app.sheet.SheetSettingRepository;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * Who may do what on a sheet: the role each user name has (clerk unless set to steward) and the
 * clerk limit, the most due a clerk may settle on a claim (none: no limit); and the sheet's floor, the
 * least live due a claim has; its terms, the days a claim has to be paid by from its date, and the terms
 * of each grade that has its own (a grade without uses the sheet's), and the grace days of each grade that
 * has them, the days past a claim's due-by before it is overdue; and its late
 * percent, what an overdue claim's due gains of its figure for every full 30 days overdue; and its policy
 * date, the date a claim's rounding turns on (none: the sheet's today); and its period numbering from,
 * the date from which a claim opened is numbered within its period (none: off); and its cap, the most a
 * person's due-total comes to (none: no cap); and its proof threshold, the most due a claim may have to be
 * settled or approved while it has no proof (none: no threshold), and each grade's own (none: the sheet's). The settings that carry a figure are dated (see
 * {@link DatedSettings}): a save records its value from a from-date, the sheet's today when none is given.
 */
@Service
public class AccessService {

    public static final String CLERK_LIMIT = DatedSettings.CLERK_LIMIT;

    public static final String FLOOR = DatedSettings.FLOOR;

    public static final String TERMS = DatedSettings.TERMS;

    /** The key of a grade's own terms: terms-A, terms-B or terms-C. */
    public static String gradeTermsKey(String grade) {
        return DatedSettings.gradeTermsKey(grade);
    }

    /** The key of a grade's grace days: grace-A, grace-B or grace-C. */
    public static String gradeGraceKey(String grade) {
        return DatedSettings.gradeGraceKey(grade);
    }

    /** The key of a grade's proof threshold: proof-threshold-A, proof-threshold-B or proof-threshold-C. */
    public static String gradeProofThresholdKey(String grade) {
        return DatedSettings.gradeProofThresholdKey(grade);
    }

    public static final String LATE_PCT = DatedSettings.LATE_PCT;

    public static final String POLICY_DATE = "policy-date";

    public static final String PERIOD_NUMBERING_FROM = "period-numbering-from";

    public static final String GRACE_DAYS = "grace-days";

    public static final String ENTRY_DATE = "entry-date";

    public static final String CAP = DatedSettings.CAP;

    public static final String PROOF_THRESHOLD = DatedSettings.PROOF_THRESHOLD;

    public static final String NOTE_THRESHOLD = DatedSettings.NOTE_THRESHOLD;

    /** A dated setting to save: its value as written (blank: none, or the starting value) and its from-date (null: the sheet's today). */
    public record Dated(String value, LocalDate from) {
    }

    private final SheetRoleRepository roles;
    private final DelegationRepository delegations;
    public SheetRole setRole(String sheetId, String user, String name, Role role) {
        sheets.load(sheetId, user);
        SheetRole row = roles.findBySheetIdAndUserName(sheetId, name).orElse(null);
        if (row == null) {
            row = roles.saveAndFlush(new SheetRole(sheetId, name, role));
        } else {
            row.setRole(role);
            roles.flush();
        }
        events.publishEvent(new RoleSet(sheetId, user, name, role.key()));
        return row;
    }

    /**
     * Save the settings given, as written (blank: none, or the default), in one change; a setting left
     * out (null) is kept as it is. A dated one is saved from its from-date.
     */
    @Transactional
    public void setSettings(String sheetId, String user, Dated clerkLimit, Dated floor, Dated terms,
            Map<String, Dated> gradeTerms, Dated latePct, String policyDate, String periodNumberingFrom, String graceDays,
            Map<String, Dated> gradeGrace, Dated cap, Dated proofThreshold, Dated noteThreshold, Map<Permission, String> permissions, String entryDate,
            Map<String, Dated> gradeProofThreshold) {
        if (clerkLimit != null) {
            setDated(sheetId, user, CLERK_LIMIT, money(clerkLimit.value(), null), clerkLimit.from(), false);
        }
        if (floor != null) {
            setDated(sheetId, user, FLOOR, money(floor.value(), Sheet.DEFAULT_FLOOR), floor.from(), true);
        }
        if (terms != null) {
            setDated(sheetId, user, TERMS, days(terms.value(), Sheet.DEFAULT_TERMS), terms.from(), false);
        }
        gradeTerms.forEach((grade, days) -> {
            if (days != null) {
                setDated(sheetId, user, gradeTermsKey(grade), days(days.value(), null), days.from(), false);
            }
        });
        if (latePct != null) {
            setDated(sheetId, user, LATE_PCT, money(latePct.value(), Sheet.DEFAULT_LATE_PCT), latePct.from(), true);
        }
        if (policyDate != null) {
            setPolicyDate(sheetId, user, policyDate.isEmpty() ? null : LocalDate.parse(policyDate));
        }
        if (periodNumberingFrom != null) {
            setPeriodNumberingFrom(sheetId, user,
                    periodNumberingFrom.isEmpty() ? null : LocalDate.parse(periodNumberingFrom));
        }
        if (graceDays != null) {
            setGraceDays(sheetId, user, graceDays.isEmpty() ? null : Integer.valueOf(graceDays));
        }
        gradeGrace.forEach((grade, days) -> {
            if (days != null) {
                setDated(sheetId, user, gradeGraceKey(grade), days(days.value(), null), days.from(), true);
            }
        });
        if (cap != null) {
            setDated(sheetId, user, CAP, money(cap.value(), null), cap.from(), true);
        }
        if (proofThreshold != null) {
            setDated(sheetId, user, PROOF_THRESHOLD, money(proofThreshold.value(), null), proofThreshold.from(), false);
        }
        gradeProofThreshold.forEach((grade, threshold) -> {
            if (threshold != null) {
                setDated(sheetId, user, gradeProofThresholdKey(grade), money(threshold.value(), null), threshold.from(), false);
            }
        });
        if (noteThreshold != null) {
            setDated(sheetId, user, NOTE_THRESHOLD, money(noteThreshold.value(), null), noteThreshold.from(), false);
        }
        permissions.forEach((permission, roles) -> {
            if (roles != null) {
                setPermission(sheetId, user, permission, roles.trim());
            }
        });
        if (entryDate != null) {
            setEntryDate(sheetId, user, entryDate.isEmpty() ? null : LocalDate.parse(entryDate));
        }
    }

    /** The roles that may take the action as set (comma separated); null when blank (the standing rule). */
    @Transactional(readOnly = true)
    public String permission(String sheetId, Permission permission) {
        return sheets.settings(sheetId).on(permission.key(), sheets.today(sheetId)).orElse(null);
    }

    /** Whether the user's role on the sheet may take the action under the sheet's permission matrix. */
    @Transactional(readOnly = true)
    public boolean allows(String sheetId, String user, Permission permission) {
        return permission.allows(permission(sheetId, permission), roleOf(sheetId, user));
    }

    /**
     * Record which roles may take an action, as written (blank: the standing rule). The permission matrix is
     * not dated: the value holds from the beginning of time, replacing the one it had.
     */
    @Transactional
    public void setPermission(String sheetId, String user, Permission permission, String roles) {
        sheets.load(sheetId, user);
        String value = roles.isEmpty() ? null : roles;
        SheetSetting row = settingRows.findBySheetIdAndKeyAndFromDate(sheetId, permission.key(), null).orElse(null);
        if (row == null) {
            settingRows.saveAndFlush(new SheetSetting(sheetId, permission.key(), null, value));
        } else {
            row.setValue(value);
            settingRows.flush();
        }
        events.publishEvent(new SettingChanged(sheetId, user, permission.key(), roles, null));
    }

    /** A figure as kept: two decimals; blank is the starting value given (null: none). */
    private static String money(String value, BigDecimal start) {
        BigDecimal figure = value.isEmpty() ? start : new BigDecimal(value).setScale(2, RoundingMode.HALF_UP);
        return figure == null ? null : figure.toPlainString();
    }

    /** A number of days as kept; blank is the starting value given (null: none). */
    private static String days(String value, Integer start) {
